/**
 * Re-implementation of the `bencoder` package's decoder, derived purely from
 * the observable behaviour of the reference program.
 *
 * The library is a thin recursive descent parser with several quirks that a
 * "correct" bencode implementation would not have; all of them are reproduced
 * here because they are observable:
 *
 *   * A byte-string length prefix is *not* validated against the remaining
 *     input — the slice is simply clamped, so `9:value` yields `b'value'` and
 *     `100:ab` yields `b'ab'`.
 *   * Dicts are built with `dict(zip(items[::2], items[1::2]))`, so an odd
 *     number of members silently drops the dangling key: `d3:cowe` -> `{}`.
 *   * An unrecognised leading byte is *printed* to stdout as an integer before
 *     the parser fails with a bare `AssertionError`.
 *   * Nothing validates the integer syntax beyond the regex, hence
 *     `i042e` -> 42 and `i-0e` -> 0.
 *
 * Line numbers in the raised frames mirror `bencoder.py` so the rendered
 * traceback matches the reference byte for byte.
 */

import { Bytes, EMPTY_BYTES, isAsciiDigitByte } from '../pytypes/bytestring.mjs';
import { pyIntFromDecimal } from '../pytypes/pyint.mjs';
import { pyDictFromFlatItems } from '../pytypes/pydict.mjs';
import { pyIntRepr } from '../pytypes/pyint.mjs';
import { printLine } from '../runtime/stdio.mjs';
import {
  PyAssertionError,
  PyAttributeError,
  PyIndexError,
  PyRecursionError,
  PyTypeError,
  pushFrame,
} from '../runtime/exceptions.mjs';

const MODULE = 'bencoder.py';

const LINE_INT_GROUP = 67; // int(m.group(1)) — m is None for malformed ints
const LINE_RECURSE = 72; // v, x = decode_first(x)
const LINE_DICT_BUILD = 78; // dict(zip(items[::2], items[1::2]))
const LINE_FIRST_BYTE = 79; // elif chr(x[0]).isdigit()
const LINE_STR_GROUP = 81; // int(m.group(1)) for the length prefix
const LINE_PRINT_BYTE = 87; // print(x[0])
const LINE_ASSERT = 88; // assert False
const LINE_DECODE_CALL = 93; // r, rest = decode_first(x)
const LINE_MALFORMED = 95; // raise TypeError('Malformed input.')

/**
 * CPython's default recursion limit is 1000 frames. Two are already in use
 * (`<module>` and `decode`), so the 999th nested `decode_first` is the one that
 * fails — `'l' * 998 + 'e' * 998` decodes, one level deeper raises.
 */
const MAX_DECODE_DEPTH = 998;

const RE_INT = /^i(-?\d+)e/;
const RE_STRING_LENGTH = /^(\d+):/;

function frame(line, func) {
  return { file: MODULE, line, func };
}

function raiseAt(error, line) {
  error.pyFrames = [frame(line, 'decode_first')];
  throw error;
}

/**
 * `decode_first(x) -> (value, rest)`
 *
 * @param {Bytes} x
 * @param {number} depth 1 for the outermost call
 * @returns {[unknown, Bytes]}
 */
export function decodeFirst(x, depth) {
  if (depth > MAX_DECODE_DEPTH) throw new PyRecursionError();

  if (x.startsWith('i')) {
    const match = RE_INT.exec(x.raw);
    if (match === null) {
      raiseAt(new PyAttributeError("'NoneType' object has no attribute 'group'"), LINE_INT_GROUP);
    }
    return [pyIntFromDecimal(match[1]), x.sliceFrom(match[0].length)];
  }

  if (x.startsWith('l') || x.startsWith('d')) {
    const isDict = x.startsWith('d');
    let rest = x.sliceFrom(1);
    const items = [];
    while (!rest.startsWith('e')) {
      let value;
      try {
        [value, rest] = decodeFirst(rest, depth + 1);
      } catch (error) {
        throw pushFrame(error, frame(LINE_RECURSE, 'decode_first'));
      }
      items.push(value);
    }
    const tail = rest.sliceFrom(1);
    if (isDict) {
      try {
        return [pyDictFromFlatItems(items), tail];
      } catch (error) {
        if (error instanceof PyTypeError) raiseAt(error, LINE_DICT_BUILD);
        throw error;
      }
    }
    return [items, tail];
  }

  // `chr(x[0]).isdigit()` — indexing an empty bytes object raises here.
  const firstByte = x.byteAt(0);
  if (firstByte === undefined) {
    raiseAt(new PyIndexError('index out of range'), LINE_FIRST_BYTE);
  }

  if (isAsciiDigitByte(firstByte)) {
    const match = RE_STRING_LENGTH.exec(x.raw);
    if (match === null) {
      raiseAt(new PyAttributeError("'NoneType' object has no attribute 'group'"), LINE_STR_GROUP);
    }
    const declaredLength = pyIntFromDecimal(match[1]);
    const bodyStart = match[0].length;
    return [x.sliceCount(bodyStart, declaredLength), x.sliceAfter(bodyStart, declaredLength)];
  }

  // The library prints the offending byte value before giving up.
  printLine(pyIntRepr(BigInt(firstByte))); // LINE_PRINT_BYTE
  raiseAt(new PyAssertionError(), LINE_ASSERT);
  return [EMPTY_BYTES, EMPTY_BYTES]; // unreachable
}

/**
 * `decode(x)` — parse one value and reject any trailing bytes.
 *
 * @param {Bytes} x
 */
export function decode(x) {
  let result;
  let rest;
  try {
    [result, rest] = decodeFirst(x, 1);
  } catch (error) {
    throw pushFrame(error, frame(LINE_DECODE_CALL, 'decode'));
  }

  if (rest.length !== 0) {
    const error = new PyTypeError('Malformed input.');
    error.pyFrames = [frame(LINE_MALFORMED, 'decode')];
    throw error;
  }
  return result;
}

/**
 * Python-flavoured exception objects plus the traceback renderer.
 *
 * The reference program is a frozen (PyInstaller) build of `test4.py`, so an
 * uncaught exception produces:
 *
 *   Traceback (most recent call last):
 *     File "test4.py", line 8, in <module>
 *       result = bencoder.decode(args.a.encode('ascii'))  # Decode bencoded string
 *                ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^
 *     File "bencoder.py", line 93, in decode
 *     File "bencoder.py", line 88, in decode_first
 *   AssertionError
 *
 * Frames inside the frozen library have no source line available, so only the
 * `File ...` line is emitted for them. Exit status for an uncaught exception
 * is 1.
 */

import { formatSourceLines, getLine } from './linecache.mjs';

export class PyException extends Error {
  constructor(typeName, detail) {
    super(detail == null ? typeName : `${typeName}: ${detail}`);
    this.typeName = typeName;
    this.detail = detail == null ? null : detail;
    /** @type {Array<{file: string, line: number, func: string}>} */
    this.pyFrames = [];
  }

  /** Final traceback line: `TypeError: Malformed input.` or bare `AssertionError`. */
  get exceptionLine() {
    return this.detail == null ? this.typeName : `${this.typeName}: ${this.detail}`;
  }
}

export class PyIndexError extends PyException {
  constructor(detail) {
    super('IndexError', detail);
  }
}

export class PyAttributeError extends PyException {
  constructor(detail) {
    super('AttributeError', detail);
  }
}

export class PyTypeError extends PyException {
  constructor(detail) {
    super('TypeError', detail);
  }
}

export class PyAssertionError extends PyException {
  constructor() {
    super('AssertionError', null);
  }
}

export class PyRecursionError extends PyException {
  constructor() {
    super('RecursionError', 'maximum recursion depth exceeded');
  }
}

export class PyUnicodeEncodeError extends PyException {
  constructor(detail) {
    super('UnicodeEncodeError', detail);
  }
}

/** Record a caller frame while an exception propagates outwards. */
export function pushFrame(error, frame) {
  if (error instanceof PyException) error.pyFrames.unshift(frame);
  return error;
}

/** The `<module>` frame of test4.py, line 8. */
const MODULE_FILENAME = 'test4.py';
const MODULE_LINENO = 8;

/**
 * CPython 3.11+ underlines the sub-expression that raised. Two spans occur
 * here, given as the 0-based byte columns the code object records for line 8
 * (`result = bencoder.decode(args.a.encode('ascii'))  # ...`):
 * the whole `bencoder.decode(...)` call, and the inner `args.a.encode('ascii')`
 * call when the ASCII encode itself fails.
 */
export const CARET_DECODE_CALL = 'decode-call';
export const CARET_ENCODE_CALL = 'encode-call';

const CARET_SPANS = {
  [CARET_DECODE_CALL]: { colno: 9, endColno: 48 },
  [CARET_ENCODE_CALL]: { colno: 25, endColno: 47 },
};

/** CPython's `traceback._RECURSIVE_CUTOFF`. */
const RECURSIVE_CUTOFF = 3;

function formatFrames(frames) {
  const lines = [];
  let lastKey = null;
  let count = 0;

  const flush = () => {
    if (count > RECURSIVE_CUTOFF) {
      const extra = count - RECURSIVE_CUTOFF;
      lines.push(`  [Previous line repeated ${extra} more time${extra > 1 ? 's' : ''}]`);
    }
  };

  for (const frame of frames) {
    const key = `${frame.file}:${frame.line}:${frame.func}`;
    if (key !== lastKey) {
      flush();
      lastKey = key;
      count = 0;
    }
    count += 1;
    if (count > RECURSIVE_CUTOFF) continue;
    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.func}`);
    if (frame.caretSpan !== undefined) {
      // Frames inside the frozen library have no readable source; the script
      // frame does, provided ./test4.py is where the process was started.
      lines.push(...formatSourceLines(getLine(frame.file, frame.line), frame.caretSpan));
    }
  }
  flush();
  return lines;
}

/**
 * Render the full traceback text (including the trailing newline) for an
 * exception escaping line 8 of test4.py.
 */
export function formatTraceback(error, caretSpan) {
  const frames = [
    {
      file: MODULE_FILENAME,
      line: MODULE_LINENO,
      func: '<module>',
      caretSpan: CARET_SPANS[caretSpan],
    },
    ...(error instanceof PyException ? error.pyFrames : []),
  ];

  const lines = ['Traceback (most recent call last):', ...formatFrames(frames)];
  lines.push(error instanceof PyException ? error.exceptionLine : String(error));
  // The frozen-executable epilogue; the number is the reporting process id.
  lines.push(`[PYI-${process.pid}:ERROR] Failed to execute script 'test4' due to unhandled exception!`);
  return `${lines.join('\n')}\n`;
}

